#include "UsdScene.hh"
#include <QFile>
#include <QDir>
#include <QFileInfo>
#include <QTemporaryDir>
#include <cassert>
#include <iostream>
#include <pxr/usd/usd/stage.h>
#include <pxr/usd/usd/variantSets.h>
